use std::future::{Future, poll_fn};
use std::pin::{Pin, pin};
use std::sync::Arc;
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, Thread};

struct Ticks {
    current: u32,
    limit: u32,
}

impl Ticks {
    fn poll_next(&mut self, _cx: &mut Context<'_>) -> Poll<Option<u32>> {
        if self.current >= self.limit {
            Poll::Ready(None)
        } else {
            self.current += 1;
            Poll::Ready(Some(self.current))
        }
    }
}

async fn next(s: &mut Ticks) -> Option<u32> {
    poll_fn(|cx| s.poll_next(cx)).await
}

fn main() {
    let total = block_on(async {
        let mut ticks = Ticks { current: 0, limit: 3 };
        let mut sum = 0;
        while let Some(n) = next(&mut ticks).await {
            println!("got {n}");
            sum += n;
        }
        sum
    });
    println!("sum = {total}");
}

