struct Closed;
struct Open;
struct Locked {
    code: u32,
}

impl Closed {
    fn open(self) -> Open {
        Open
    }
    fn lock(self, code: u32) -> Locked {
        Locked { code }
    }
}

impl Open {
    fn close(self) -> Closed {
        Closed
    }
}

impl Locked {
    fn unlock(self, code: u32) -> Result<Closed, Locked> {
        if code == self.code { Ok(Closed) } else { Err(self) }
    }
}

fn main() {
    let door = Closed;
    let door = door.open();
    println!("opened");
    let door = door.close();
    println!("closed");
    let door = door.lock(1234);
    println!("locked");
    let door = match door.unlock(1111) {
        Ok(d) => d,
        Err(still_locked) => {
            println!("wrong code");
            still_locked.unlock(1234).ok().unwrap()
        }
    };
    println!("unlocked");
    let _ = door;
