fn swap_ends(v: &mut [i32]) {
    if v.is_empty() {
        return;
    }
    let len = v.len();
    let p = v.as_mut_ptr();
    // SAFETY: v is non-empty, so p and p.add(len - 1) are both in bounds; ptr::swap allows them to be equal
    unsafe {
        std::ptr::swap(p, p.add(len - 1));
    }
}

fn main() {
    let mut a = [1, 2, 3, 4, 5];
    let mut b = [7];
    let mut c: [i32; 0] = [];
    swap_ends(&mut a);
    swap_ends(&mut b);
    swap_ends(&mut c);
    println!("{a:?}");
    println!("{b:?}");
    println!("{c:?}");
}
